import { useCallback, useEffect, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Applicant } from '../types/app.types';

export interface UseApplicantsListOptions {
    /** Defaults to 10 to match the applicants list UI. */
    pageSize?: number;
}

export function useApplicantsList(options: UseApplicantsListOptions = {}) {
    const pageSize = options.pageSize ?? 10;

    const [data, setData] = useState<Applicant[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [pageIndex, setPageIndex] = useState(0);
    const [globalFilter, setGlobalFilter] = useState('');

    const fetchData = useCallback(async () => {
        setIsLoading(true);

        try {
            const response = await apiGet({
                endpoint: endpoints.applicant.list,
                queryParams: { page: pageIndex + 1, search: globalFilter },
            });

            setData(response.data.data.data);
            setPageCount(Math.ceil(response.data.data.pagination.total / pageSize));
            setTotalCount(response.data.data.pagination.total);
        } catch {
            setData([]);
        } finally {
            setIsLoading(false);
        }
    }, [pageIndex, globalFilter, pageSize]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    return {
        data,
        setData,
        pageCount,
        totalCount,
        isLoading,
        pageIndex,
        setPageIndex,
        globalFilter,
        setGlobalFilter,
        fetchData,
        pageSize,
    };
}
